<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {Table,Modal,Select,Checkbox} from 'ant-design-vue'
import StatePanel from '@starbeacon/shared/components/StatePanel.vue'
import {formatTime} from '@starbeacon/shared/types.ts'
import {useModels} from '../models/useModels'
import {checkClass} from '../models/models'
import {blankRequest,kindNames,stateNames,type AnalysisKind} from './analysis'
import {useAnalysis} from './useAnalysis'
import AnalysisDetail from './AnalysisDetail.vue'
const models=useModels(),state=useAnalysis('reports'),{items,next,pending,error,busy,actionError,unconfirmed,selected,loading,detailError}=state
const open=ref(false),detailOpen=ref(false),kind=ref<'daily'|'weekly'|'monthly'>('daily'),period=ref(new Date(Date.now()-86400000).toLocaleDateString('en-CA',{timeZone:'Asia/Shanghai'})),timezone=ref('Asia/Shanghai'),provider=ref(''),allowed=ref(false),viewing=ref('')
const providers=computed(()=>models.items.value.filter(p=>p.enabled))
watch(()=>[kind.value,period.value,timezone.value,provider.value,providers.value.find(p=>p.id===provider.value)?.revision],()=>{allowed.value=false})
const columns=[{title:'报告',key:'name',width:230},{title:'状态',key:'state',width:140},{title:'统计范围',key:'window',width:280},{title:'生成时间',key:'time',width:190},{title:'操作',key:'action',width:110,fixed:'right' as const}]
async function generate(){if(busy.value)return;let job;if(unconfirmed.value)job=await state.confirm();else{const r=blankRequest(kind.value);r.period=period.value;r.timezone=timezone.value;if(provider.value){const p=providers.value.find(row=>row.id===provider.value);if(!p)return;r.provider_id=p.id;r.provider_revision=p.revision;r.allow_context=allowed.value}job=await state.submit(r)}if(job){open.value=false;detailOpen.value=true;viewing.value=job.id;allowed.value=false}}
async function show(id:string){state.clear();viewing.value=id;detailOpen.value=true;await state.loadJob(id)}
function closeDetail(){detailOpen.value=false;state.clear()}
</script>
<template>
 <header class="page-header"><div><h1>报告中心</h1><p class="page-description">生成安全日报、周报与月报，复核冻结的统计来源和模型调查建议。</p></div><div class="filter-actions"><a-button :loading="pending" @click="state.refresh()">刷新</a-button><a-button type="primary" :disabled="busy" @click="open=true">生成报告</a-button></div></header>
 <a-alert v-if="models.error.value" type="warning" :message="`${models.error.value}。可生成统计报告。`" show-icon class="section-gap"/>
 <section class="panel"><div class="panel-header"><h2>报告记录</h2><span>不同运行保留独立修订</span></div><a-alert v-if="error&&items.length" type="error" :message="error+'。当前显示上次成功读取的报告。'" show-icon class="section-gap"><template #action><a-button @click="state.refresh()">重试</a-button></template></a-alert><StatePanel :loading="pending&&!items.length" :error="items.length?'':error" :empty="items.length===0" description="暂无报告记录，可选择自然日、完整周或自然月生成报告。" @retry="state.refresh()"><div class="table-wrap"><Table :columns="columns" :data-source="[...items]" row-key="id" :pagination="false" :scroll="{x:950}"><template #bodyCell="{column,record}"><template v-if="column.key==='name'">{{kindNames[record.kind as AnalysisKind]}} · {{record.title}}<small class="record-id">修订 {{record.revision}}</small></template><template v-else-if="column.key==='state'"><span :class="['status',checkClass(record.state)]">{{stateNames[record.state]??'其他处理状态'}}</span></template><template v-else-if="column.key==='window'">{{formatTime(record.window.start)}}<br>至 {{formatTime(record.window.end)}}</template><template v-else-if="column.key==='time'">{{formatTime(record.created_at)}}</template><a-button v-else-if="column.key==='action'" type="link" size="small" @click="show(record.id)">查看</a-button></template></Table></div><a-button v-if="next" :loading="pending" class="section-gap" @click="state.refresh(next,true)">查看更多报告</a-button></StatePanel></section>
 <Modal :open="open" title="生成安全报告" :width="640" :footer="null" :mask-closable="false" :closable="!busy&&!unconfirmed" :keyboard="!busy&&!unconfirmed" @cancel="open=false"><a-alert v-if="actionError" type="error" :message="actionError" show-icon class="section-gap"/><a-alert v-if="unconfirmed" type="warning" message="提交结果尚未确认，请确认原请求后继续。" show-icon class="section-gap"/><a-form layout="vertical" :disabled="busy||unconfirmed" @finish="generate"><div class="report-fields"><a-form-item label="报告类型"><Select v-model:value="kind" aria-label="报告类型" :options="[{value:'daily',label:'安全日报'},{value:'weekly',label:'安全周报'},{value:'monthly',label:'安全月报'}]"/></a-form-item><a-form-item label="周期内日期"><input v-model="period" type="date" class="report-date" aria-label="周期内日期" required :disabled="busy||unconfirmed"></a-form-item></div><a-form-item label="报告时区"><a-input v-model:value="timezone" aria-label="报告时区" :maxlength="128" placeholder="Asia/Shanghai"/></a-form-item><p class="muted section-gap">日报使用所选自然日；周报使用该日期所在的完整周（周一至周日）；月报使用该日期所在自然月。仅生成已经结束的周期，夏令时按报告时区计算。</p><a-form-item label="智能总结"><Select v-model:value="provider" aria-label="报告模型" :options="[{value:'',label:'仅生成统计报告'},...providers.map(p=>({value:p.id,label:`${p.name} · ${p.model}`,disabled:!state.available.value}))]"/></a-form-item><Checkbox v-if="provider" v-model:checked="allowed">允许本次模型调用使用周期统计</Checkbox><p class="muted section-gap">模型调用可能计费。未启用智能总结或模型失败时，统计来源仍可复核；生成报告不会自动发布或通知他人。</p></a-form><div class="filter-actions report-actions"><a-button :disabled="busy||unconfirmed" @click="open=false">取消</a-button><a-button type="primary" :loading="busy" :disabled="busy||!unconfirmed&&(!period||!timezone||!!provider&&!allowed)" @click="generate">{{unconfirmed?'确认提交结果':'开始生成'}}</a-button></div></Modal>
 <AnalysisDetail :open="detailOpen" :job="selected" :loading="loading" :error="detailError" :busy="busy" @close="closeDetail" @retry="state.loadJob(viewing)" @cancel="state.cancel"/>
</template>
<style scoped>.report-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.report-date{width:100%;min-height:32px;border:1px solid var(--line);border-radius:6px;padding:4px 10px;background:var(--surface);color:var(--text);font:inherit}.report-date:focus{outline:2px solid var(--primary);outline-offset:2px}.report-date:disabled{background:var(--control-disabled);color:var(--muted)}.report-actions{justify-content:flex-end;margin-top:12px}@media(max-width:640px){.report-fields{grid-template-columns:1fr;gap:0}}</style>
